  ListUnitsMethodHandler::Unit u;
  u.id = id;
  u.description = "desc " + id;
  u.load_state = "loaded";
  u.active_state = "active";
  u.sub_state = "running";
  u.following = "";
  u.path = "/org/freedesktop/systemd1/unit/x";
  u.job_id = 42U;
  u.job_type = "start";
  u.job_path = "/org/freedesktop/systemd1/job/1";
  return u;
}

int main() {
  // getUnitType cases
  assert(getUnitType("sshd.service") == "service");
  assert(getUnitType("dbus.socket") == "socket");
  assert(getUnitType("apt-daily.timer") == "timer");
  assert(getUnitType("foo-bar.baz.service") == "service");
  assert(getUnitType("plainunitname") == "");
  assert(getUnitType("") == "");
  assert(getUnitType("trailingdot.") == "");
  std::cout << "getUnitType: ok\n";

  // parse two units
  std::vector<ListUnitsMethodHandler::Unit> expected = {
      makeUnit("sshd.service"), makeUnit("apt-daily.timer")};
  DBusMessage* reply = createReply(expected);
  DBusMessageIter mit{};
  dbus_message_iter_init(reply, &mit);
  assert(dbus_message_iter_get_arg_type(&mit) == DBUS_TYPE_ARRAY);
  DBusMessageIter ait{};
  dbus_message_iter_recurse(&mit, &ait);
  ListUnitsMethodHandler::Output out;
  Status s = parseListUnitsReply(out, ait);
  assert(s.ok());
  assert(out.size() == 2U);
  assert(out[0].id == "sshd.service");
  assert(out[0].job_id == 42U);
  assert(out[0].path == "/org/freedesktop/systemd1/unit/x");
  assert(out[0].sub_state == "running");
  assert(out[1].id == "apt-daily.timer");
  dbus_message_unref(reply);
  std::cout << "parseListUnitsReply (2 units): ok\n";

  // empty array
  reply = createReply({});
  dbus_message_iter_init(reply, &mit);
  dbus_message_iter_recurse(&mit, &ait);
  out.clear();
  s = parseListUnitsReply(out, ait);
  assert(s.ok());
  assert(out.empty());
  dbus_message_unref(reply);
  std::cout << "parseListUnitsReply (empty): ok\n";

  // wrong type rejection
  reply = dbus_message_new(DBUS_MESSAGE_TYPE_METHOD_RETURN);
  DBusMessageIter root{};
  dbus_message_iter_init_append(reply, &root);
  const char* dummy = "nope";
  dbus_message_iter_append_basic(&root, DBUS_TYPE_STRING, &dummy);
  DBusMessageIter wrong{};
  dbus_message_iter_init(reply, &wrong);
  out.clear();
  s = parseListUnitsReply(out, wrong);
  assert(!s.ok());
  dbus_message_unref(reply);
  std::cout << "parseListUnitsReply (wrong type rejected): ok\n";

  std::cout << "ALL TESTS PASSED\n";
  return 0;
}
EOF
